DO $baseline$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_constraint WHERE conrelid='public.sales_intelligence_attributions'::regclass AND conname='sales_intelligence_attributions_ambiguity_ck') THEN
 ALTER TABLE public."sales_intelligence_attributions" ADD CONSTRAINT "sales_intelligence_attributions_ambiguity_ck" CHECK (ambiguity_status = ANY (ARRAY['none'::text, 'ambiguous_multiple_candidates'::text]));
 END IF;
END $baseline$;
DO $baseline$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_constraint WHERE conrelid='public.sales_intelligence_attributions'::regclass AND conname='sales_intelligence_attributions_candidate_count_ck') THEN
 ALTER TABLE public."sales_intelligence_attributions" ADD CONSTRAINT "sales_intelligence_attributions_candidate_count_ck" CHECK (candidate_count >= 0);
 END IF;
END $baseline$;
DO $baseline$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_constraint WHERE conrelid='public.sales_intelligence_attributions'::regclass AND conname='sales_intelligence_attributions_confidence_ck') THEN
 ALTER TABLE public."sales_intelligence_attributions" ADD CONSTRAINT "sales_intelligence_attributions_confidence_ck" CHECK (confidence_score >= 0::numeric AND confidence_score <= 1::numeric);
 END IF;
END $baseline$;
DO $baseline$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_constraint WHERE conrelid='public.sales_intelligence_attributions'::regclass AND conname='sales_intelligence_attributions_identity_conflict_ck') THEN
 ALTER TABLE public."sales_intelligence_attributions" ADD CONSTRAINT "sales_intelligence_attributions_identity_conflict_ck" CHECK (identity_conflict = ANY (ARRAY['none'::text, 'phone_vs_customer_id_conflict'::text]));
 END IF;
END $baseline$;
